const chargePeople = c => {if(!c.people)c.people=(gById(c.group).people||people.slice(0,c.members||gById(c.group).members)).map((p,i)=>({...p,id:p.id||'member-'+i}));return c.people.map((p,i)=>({...p,id:p.id||'member-'+i}));};
const equalAllocation = (total,count) => {const cents=Math.round(total*100),base=Math.floor(cents/count);return Array.from({length:count},(_,i)=>(base+(i<cents%count?1:0))/100);};
const currentAllocation = c => state.proposals[c.id] || c.allocation || equalAllocation(c.total,chargePeople(c).length);
const currentPersonalAllocation = c => currentAllocation(c)[0];
const currentApprovalCount = c => (state.approved[c.id]?1:0)+(state.proposals[c.id]?0:c.initialApprovals??1);
