function initialItems(c){return c.id==='juniper'?[['burrata','Burrata',16,[2]],['pizza','Margherita pizza',24,[0]],['rigatoni','Rigatoni',28,[1]],['branzino','Branzino',36,[2,3]],['tiramisu','Tiramisu',10,[1,3]],['water','Sparkling water',6,[0]]].map(([id,name,amount,ids])=>({id,name,amount,assignees:ids.map(i=>chargePeople(c)[i].id)})):[];}
function currentProposal(c){return state.proposalDetails[c.id]||{method:state.publishedMethods[c.id]||c.initialMethod||'equal',allocation:currentAllocation(c),items:initialItems(c),tax:c.id==='juniper'?10.2:0,tip:c.id==='juniper'?24:0,receipt:c.id==='juniper'?{kind:'sample',name:'Juniper sample receipt',itemSource:'sample'}:null};}
function splitView(c){const draft=current().type==='split-edit'?state.splitDrafts[c.id]:null;const proposal=draft||currentProposal(c),result=draft?calculateProposal(c,draft):{allocation:currentAllocation(c)};return {method:proposal.method,draft:!!draft,allocations:result.allocation||Array(chargePeople(c).length).fill(null),proposal,error:result.error};}
function moneyCents(value){const number=Number(value);return value!==''&&Number.isFinite(number)&&number>=0&&Math.abs(number*100-Math.round(number*100))<.00001?Math.round(number*100):null;}
function distributeWeighted(cents,weights){const total=weights.reduce((a,b)=>a+b,0);if(!total)return weights.map(()=>0);const values=weights.map(w=>Math.floor(cents*w/total));const order=weights.map((w,i)=>({i,remainder:cents*w%total})).sort((a,b)=>b.remainder-a.remainder||a.i-b.i);for(let i=0,left=cents-values.reduce((a,b)=>a+b,0);i<left;i++)values[order[i].i]++;return values;}
function calculateProposal(c,p){const members=chargePeople(c),total=Math.round(c.total*100);if(p.method!=='item'&&p.items.length){const receiptCheck=calculateProposal(c,{...p,method:'item'});if(receiptCheck.error)return receiptCheck;}if(p.method==='equal')return {allocation:equalAllocation(c.total,members.length)};if(p.method==='custom'){const cents=p.allocation.map(moneyCents);if(cents.length!==members.length||cents.some(n=>n===null)||cents.reduce((a,b)=>a+b,0)!==total)return {error:'Member shares must add up exactly to '+money(c.total)+'.'};return {allocation:cents.map(n=>n/100)};}
 if(!p.receipt||!p.items.length)return {error:'Add a receipt and its items before submitting an itemized split.'};const tax=moneyCents(p.tax),tip=moneyCents(p.tip);if(tax===null||tip===null)return {error:'Enter valid tax and tip amounts with at most two decimal places.'};const base=members.map(()=>0),seen=new Set();let subtotal=0;for(const item of p.items){const amount=moneyCents(item.amount);if(!item.name.trim()||amount===null||amount<=0)return {error:'Give every item a name and a positive amount.'};if(seen.has(item.id))return {error:'Every item needs its own identity.'};seen.add(item.id);if(!item.assignees.length||new Set(item.assignees).size!==item.assignees.length||item.assignees.some(id=>!members.some(m=>m.id===id)))return {error:'Assign every item to at least one group member.'};const indices=item.assignees.map(id=>members.findIndex(m=>m.id===id)).sort((a,b)=>a-b);const shares=equalAllocation(amount/100,indices.length);indices.forEach((index,i)=>base[index]+=Math.round(shares[i]*100));subtotal+=amount;}
 if(subtotal+tax+tip!==total)return {error:'Items, tax and tip must total '+money(c.total)+'. Currently '+money((subtotal+tax+tip)/100)+'.'};const taxes=distributeWeighted(tax,base),tips=distributeWeighted(tip,base);return {allocation:base.map((n,i)=>(n+taxes[i]+tips[i])/100)};
}
function beginSplitEdit(id){const c=pending.find(c=>c.id===id);state.splitDrafts[id]={...clone(currentProposal(c)),allocation:[...currentAllocation(c)],generation:++state.draftSequence};push('split-edit',id);}
function proposalSignature(p){return JSON.stringify({method:p.method,allocation:p.allocation.map(moneyCents),receipt:p.receipt,items:p.items.map(i=>({id:i.id,name:i.name.trim(),amount:moneyCents(i.amount),assignees:[...i.assignees].sort()})),tax:moneyCents(p.tax),tip:moneyCents(p.tip)});}
function submitSplitProposal(id){const c=pending.find(c=>c.id===id),draft=state.splitDrafts[id];if(!draft)return {error:'Begin editing before submitting a proposal.'};const result=calculateProposal(c,draft);if(result.error)return result;const published={...clone(draft),allocation:result.allocation};delete published.generation;delete published.uploadVersion;const unchanged=proposalSignature(published)===proposalSignature(currentProposal(c));if(!unchanged){state.proposalDetails[id]=published;state.proposals[id]=[...result.allocation];state.publishedMethods[id]=published.method;state.approved[id]=false;}return {changed:!unchanged};}
function acceptSplit(id){const c=pending.find(c=>c.id===id);if(current().type==='split-edit')return {error:'Submit or cancel your draft before accepting.'};const p=currentProposal(c);if(p.method==='item'){const result=calculateProposal(c,p);if(result.error)return result;}state.approved[id]=true;return {accepted:true};}

const groupPhotos={apartment:'assets/apartment.jpg',weekend:'assets/weekend.jpg',roadtrip:'assets/roadtrip.jpg'};
const groupPhoto=g=>g.photo||groupPhotos[g.id];
const stamp=(g,size='')=>`<span class="group-icon ${g.tone} ${size} ${groupPhoto(g)?'has-photo':''}">${groupPhoto(g)?`<img src="${esc(groupPhoto(g))}" alt="" loading="lazy" decoding="async">`:icon(g.icon)}</span>`;
const merchantLogoKeys={spotify:'spotify',wholefoods:'wholefoods',ikea:'ikea',bluebottle:'bluebottle',groceries:'traderjoes',shell:'shell',costco:'costco'};
const merchantKey=c=>merchantLogoKeys[c.id]||({'spotify':'spotify','whole foods':'wholefoods','ikea':'ikea','blue bottle':'bluebottle','trader joe’s':'traderjoes',"trader joe's":"traderjoes",'shell':'shell','costco':'costco'}[String(c.merchant||c.name).toLowerCase()]);
const merchantMark=(c,large=false)=>{const key=merchantKey(c);return `<span class="merchant-mark ${large?'large':''} ${key||'generic'}" aria-hidden="true">${key?`<img src="assets/logo-${key}.${key==='wholefoods'?'png':'svg'}" alt="">`:icon(c.icon||'shopping-bag')}</span>`;};
const button=(label,action,extra='',type='')=>`<button type="button" class="button ${type}" data-action="${action}" ${extra}>${label}</button>`;
const backbar=(title,right='')=>`<header class="backbar"><button class="icon-btn" data-action="back" aria-label="Go back">${icon('arrow-left')}</button><strong>${esc(title)}</strong>${right||'<span class="spacer"></span>'}</header>`;
const avatar=(p=people[0],large=false)=>`<span class="avatar ${p.tone} ${large?'large':''}">${p.initials}</span>`;
function toast(message){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
function current(){return state.stack.at(-1)||{type:state.tab};}
function routeKey(){const r=current();return r.type+':'+(r.id||'');}
function saveScroll(){const s=$('.screen');if(s)state.scroll[routeKey()]=s.scrollTop;}
function push(type,id){saveScroll();state.stack.push({type,id});render(true);}
function back(){saveScroll();const route=current();if(route.type==='split-edit')delete state.splitDrafts[route.id];state.stack.pop();render(true);}
function nav(tab){saveScroll();state.splitDrafts={};state.stack=[];state.tab=tab;render();}
function navBar(){return `<nav class="bottom-nav" aria-label="Main navigation">${[['home','home','Home'],['groups','grid','Groups'],['spending','bar-chart-2','Spending']].map(([id,i,t])=>`<button class="nav-button ${state.tab===id?'active':''}" data-action="tab" data-tab="${id}" ${state.tab===id?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span>${t}</button>`).join('')}</nav>`;}
function rootHeader(){return `<header class="topbar root-header"><button class="icon-btn" data-action="profile" aria-label="Open your profile">${avatar()}</button><button class="icon-btn" data-action="notifications" aria-label="Open notifications">${icon('bell')}${state.notice?'<span class="notification-dot"></span>':''}</button></header>`;}
function pendingCard(c){const g=gById(c.group);return `<button class="pending-card" data-action="split" data-id="${c.id}" aria-label="Review ${esc(c.name)}, your share ${money(currentPersonalAllocation(c))}, ${esc(g.name)}${state.approved[c.id]?', accepted and waiting for others':''}"><div><div class="pending-title">${esc(c.name)}${state.approved[c.id]?' · Waiting':''}</div><div class="pending-amount">${money(currentPersonalAllocation(c))}</div></div><div class="group-stamp">${stamp(g)}</div></button>`;}
function groupActions(){return `<div class="actions-pair groups-actions">${button(icon('plus')+' Create a group','create')}${button('Invitations <span class="tiny-badge">'+invites.filter(i=>!state.invites[i.id]).length+'</span>','invitations','','secondary')}</div>`;}
function home(){return `${rootHeader()}<h1 class="greeting">Hey, ${esc(state.displayName)} ${'<span style="font-size:22px">✦</span>'}</h1><div class="eyebrow greeting-sub">Good evening</div><section class="hero" aria-label="October settled spending"><div class="hero-head"><span>Your spend this month</span><span>October 2026</span></div><div class="hero-amount">${money(spendingTotal(9)).split('.')[0]}<span class="cents">.${money(spendingTotal(9)).split('.')[1]}</span></div>${homeSparkline()}<div class="hero-foot"><span>OCT 1</span><span>OCT 17</span></div></section><div class="section-heading"><h2>Pending charges</h2></div><div class="pending-list">${pending.slice(0,3).map(pendingCard).join('')}</div>${pending.length>3?button(icon('arrow-right')+' +'+(pending.length-3)+' more','all-pending','aria-label="See all '+pending.length+' pending charges"','more-pending'):''}`;}
function allPending(){return `${backbar('')}<h1 class="page-title charges-title">Charges</h1><div class="pending-list">${pending.map(pendingCard).join('')}</div>`;}
function groupsPage(){return `${rootHeader()}<div class="groups-page-heading"><div><h1 class="page-title">Your groups</h1><p class="eyebrow">Better together, everyday.</p></div></div>${groupActions()}<div class="groups-grid">${groups.map(g=>`<button class="group-tile" data-action="group" data-id="${g.id}">${stamp(g)}<h2>${esc(g.name)}</h2><p>${g.members} members · ${g.forming?'Invites pending':money(g.balance)+' yours'}</p></button>`).join('')}</div>`;}
function cardVisual(g){return `<div class="bank-card ${state.frozen[g.id]?'frozen':''}" role="img" aria-label="${esc(g.name)} sample virtual card ending 4826${state.frozen[g.id]?', frozen':''}"><div class="bank-top"><span>chipin<span style="color:#7a9eff">.</span></span>${icon(state.frozen[g.id]?'lock':'credit-card')}</div><div class="bank-chip"></div><div class="bank-number">•••• &nbsp; •••• &nbsp; •••• &nbsp; 4826</div><div class="bank-bottom"><span>${esc(state.displayName.toUpperCase())} ZACHARIAS<br><span style="font-size:8px;display:block;margin-top:5px;color:#8397b7">${esc(g.name.toUpperCase())}</span></span><strong>VISA</strong></div></div>`;}
function groupSpendPanel(g){const total=spendingTotal(9,g.id),maximum=Math.max(50,Math.ceil(total/50)*50);return `<div class="group-spend-panel"><div class="row"><span class="eyebrow">Your group spending</span><span class="eyebrow">October</span></div><strong>${money(total)}</strong><svg viewBox="0 0 310 100" preserveAspectRatio="none" role="img" aria-label="${esc(g.name)} settled spending through October 17: ${money(total)}. Scale zero to ${money(maximum)}.">${[[8,maximum],[52,maximum/2],[96,0]].map(([y,n])=>`<text x="0" y="${y+3}" fill="#626a78" font-size="8">$${n}</text><line x1="35" y1="${y}" x2="310" y2="${y}" stroke="#e8ebf0" stroke-dasharray="2 4"/>`).join('')}<polyline transform="translate(35 0)" points="${cumulativePoints(g.id,275,96,maximum)}" fill="none" stroke="#2459e8" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="row"><span class="eyebrow">Settled · Through Oct 17</span><button class="text-action" data-action="group-menu" data-menu="statistics" data-id="${g.id}">View details ${icon('arrow-right')}</button></div></div>`;}
function groupCarousel(g){const panel=state.carousel[g.id]||0;return `<div class="group-carousel" data-carousel="${g.id}" tabindex="0" role="region" aria-roledescription="carousel" aria-label="Group card and spending. Use left or right arrow to switch."><div class="carousel-track" style="transform:translateX(-${panel*50}%)"><div class="carousel-panel" ${panel===1?'inert':''}><button class="card-launch" data-action="wallet" data-id="${g.id}" aria-label="Open mock Apple Pay for ${esc(g.name)}">${cardVisual(g)}</button></div><div class="carousel-panel" ${panel===0?'inert':''}>${groupSpendPanel(g)}</div></div></div><div class="carousel-controls" aria-label="Choose card or spending">${['Card','Spending'].map((name,i)=>`<button data-action="carousel" data-id="${g.id}" data-panel="${i}" aria-pressed="${panel===i}"><span class="carousel-dot"></span>${name}</button>`).join('')}</div>`;}
function setCarousel(id,panel){state.carousel[id]=Number(panel);const carousel=document.querySelector('[data-carousel="'+id+'"]');if(!carousel)return;carousel.querySelector('.carousel-track').style.transform='translateX(-'+panel*50+'%)';carousel.querySelectorAll('.carousel-panel').forEach((el,i)=>el.inert=i!==Number(panel));document.querySelectorAll('[data-action="carousel"][data-id="'+id+'"]').forEach((el,i)=>el.setAttribute('aria-pressed',String(i===Number(panel))));}
function groupDetail(id){const g=gById(id);return `${backbar('Group overview',`<button class="icon-btn" data-action="group-menu" data-id="${id}" data-menu="settings" aria-label="Group settings">${icon('settings')}</button>`)}<div class="group-identity">${stamp(g,'overview-photo')}<h1>${esc(g.name)}</h1></div>${groupCarousel(g)}<div class="fund-metrics"><div><small>Group buying power</small><div class="big">${money(g.power)}</div></div><div><small>Your balance</small><strong>${money(g.balance)}</strong></div><div><small>Available after holds</small><strong>${money(g.available)}</strong></div></div>${g.forming?'<div class="callout">'+icon('info')+'<span>This group activates after all invitations are resolved and at least two people join. No contribution has been collected in this preview.</span></div>':''}<div class="list-menu">${[['funds','dollar-sign','Funds','Add or withdraw'],['card','credit-card','Card controls','Details and freeze card']].map(([m,i,t,detail])=>`<button class="menu-row" data-action="group-menu" data-id="${id}" data-menu="${m}">${icon(i)}<span class="menu-copy">${t}<small>${detail}</small></span>${icon('chevron-right')}</button>`).join('')}</div><div class="list-menu group-history-menu"><button class="menu-row" data-action="group-menu" data-id="${id}" data-menu="history">${icon('file-text')}<span class="menu-copy">Charge history<small>Pending and settled purchases</small></span>${icon('chevron-right')}</button></div>`;}
const colors={apartment:'#2459e8',weekend:'#b57439',roadtrip:'#8a70bd'};
const monthCharges = month => month === 9 ? charges : [];
const spendingTotal = (month, groupId) => monthCharges(month).filter(c => !groupId || c.group === groupId).reduce((sum,c) => sum + Math.round(c.amount * 100), 0) / 100;

function cumulativePoints(groupId, width, height, maximum) {
  const series = monthCharges(9).filter(c => !groupId || c.group === groupId);
  return Array.from({length:17},(_,index) => {
    const day=index+1;
    const cents=series.filter(c => Number(c.date.split(' ')[1]) <= day).reduce((sum,c) => sum+Math.round(c.amount*100),0);
    return `${(index * width / 16).toFixed(2)},${(height - cents / 100 / maximum * (height-8)).toFixed(2)}`;
  }).join(' ');
}
function homeSparkline(){const points=cumulativePoints(null,320,75,spendingTotal(9));return `<svg class="hero-chart" viewBox="0 0 320 80" preserveAspectRatio="none" role="img" aria-label="Cumulative settled spending from October 1 through October 17: ${money(spendingTotal(9))}"><polygon points="0,80 ${points} 320,80" fill="#497cff" fill-opacity=".12"/><polyline points="${points}" fill="none" stroke="#6890ff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}

function spending(groupId){
  const selected=groupId||state.filter==='all'?null:state.filter;
  const activeGroups=groups.filter(g=>!g.forming&&(!groupId||g.id===groupId));
  const shown=activeGroups;
  const total=shown.reduce((sum,g)=>sum+spendingTotal(state.month,g.id),0);
  const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
  const visibleCharges=[...pending.filter(c=>c.month===state.month).map(c=>({...c,isPending:true})),...monthCharges(state.month)].filter(c=>(!groupId||c.group===groupId)&&(groupId||state.filter==='all'||c.group===state.filter));
  const hasData=monthCharges(state.month).length>0;
  return `${groupId?backbar('Group statistics'):rootHeader()+'<h1 class="page-title">Spending</h1><p class="eyebrow">A clearer picture of your shared life.</p>'}<div class="month-selector"><button data-action="month" data-dir="-1" aria-label="Previous month" ${state.month===0?'disabled':''}>${icon('chevron-left')}</button><strong>${months[state.month]} 2026</strong><button data-action="month" data-dir="1" aria-label="Next month" ${state.month===11?'disabled':''}>${icon('chevron-right')}</button></div><section class="card-section" style="padding:21px 19px"><div class="eyebrow">${groupId?'Your spending · '+esc(gById(groupId).name):'Your total spending'}</div><div class="spending-total">${money(total)}</div><p class="spending-caption">${hasData?'Settled purchases · Through October 17':'No sample purchases this month'}</p>${hasData?`<div class="chart-wrap"><svg class="spending-chart" viewBox="0 0 ${groupId?346:310} 178" preserveAspectRatio="none" role="img" aria-label="Cumulative settled spending through October 17. ${shown.map(g=>g.name+' '+money(spendingTotal(state.month,g.id))).join(', ')}">${groupId?[[8,520],[82.5,260],[157,0]].map(([y,n])=>`<text x="0" y="${y+3}" fill="#626a78" font-size="8">$${n}</text>`).join(''):''}<g transform="translate(${groupId?36:0} 0)">${[25,66,107,148].map(y=>`<line x1="0" y1="${y}" x2="310" y2="${y}" stroke="#e8ebf0" stroke-dasharray="3 5"/>`).join('')}${shown.map(g=>`<polyline points="${cumulativePoints(g.id,310,157,520)}" fill="none" stroke="${selected&&selected!==g.id?'#c4cad4':colors[g.id]||'#2459e8'}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="310" cy="${157-spendingTotal(state.month,g.id)/520*149}" r="3.5" fill="${selected&&selected!==g.id?'#c4cad4':colors[g.id]||'#2459e8'}" stroke="white" stroke-width="2"/>`).join('')}</g></svg><div class="chart-axis"><span>1 Oct</span><span>5</span><span>9</span><span>13</span><span>17</span></div></div>`:'<div class="empty"><p>There is no sample spending history for this month.</p></div>'}<div class="legend">${activeGroups.map(g=>`<button class="${selected===g.id?'selected':selected?'dimmed':''}" data-action="legend" data-id="${g.id}" aria-pressed="${!selected||selected===g.id}"><span class="legend-dot" style="background:${colors[g.id]||'#2459e8'}"></span>${esc(g.name)}</button>`).join('')}</div></section><div class="section-heading"><h2>All charges</h2>${!groupId?`<select class="filter-select" id="charge-filter" aria-label="Filter charges by group"><option value="all">All groups</option>${activeGroups.map(g=>`<option value="${g.id}" ${state.filter===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select>`:''}</div>${visibleCharges.length?visibleCharges.map(chargeRow).join(''):'<div class="empty"><p>No charges match this month and selection.</p></div>'}`;
}
function chargeRow(c){return `<button class="charge-row ${c.isPending?'is-pending':''}" data-action="${c.isPending?'split':'charge'}" data-id="${c.id}" aria-label="${esc(c.name)}, ${c.isPending?'pending, current share '+money(currentPersonalAllocation(c)):'settled, '+money(c.amount)}, ${esc(gById(c.group).name)}">${c.isPending?'':merchantMark(c,true)}<span class="charge-copy"><strong>${esc(c.name)}</strong><small>${esc(gById(c.group).name)} · ${c.date}</small></span><span class="charge-price">${money(c.isPending?currentPersonalAllocation(c):c.amount)}<small>${c.isPending?'Pending':'Settled'}</small></span></button>`;}
function chargeHistory(id){const g=gById(id),rows=[...pending.filter(c=>c.group===id).map(c=>({...c,isPending:true})),...charges.filter(c=>c.group===id)];return `${backbar('Charge history')}<h1 class="page-title">${esc(g.name)}</h1><p class="page-sub">Pending and settled purchases</p>${rows.length?rows.map(chargeRow).join(''):'<div class="empty"><p>No purchases in this group yet.</p></div>'}`;}
function splitSummary(c,draft){const result=draft?calculateProposal(c,draft):null;return `<div class="split-summary"><h1>${draft?'Current share':'Your share'}</h1><div class="share" id="split-share">${money(currentPersonalAllocation(c))}</div><p class="split-summary-context">of ${money(c.total)} · ${esc(gById(c.group).name)}</p>${draft?`<p class="sticky-draft" id="sticky-draft-amount">${result.error?'Draft incomplete':'Draft '+money(result.allocation[0])} · not sent</p>`:''}</div>`;}
function memberAllocations(c,p,editing=false){const result=editing?calculateProposal(c,p):{allocation:currentAllocation(c)},members=chargePeople(c);return `<section class="card-section"><div class="row"><h2 style="margin:0">The split</h2><span class="pill ${editing?'pending':''}">${editing?'Unsent draft':methodName(p.method)}</span></div>${members.map((person,i)=>`<div class="person-row">${avatar(person)}<div class="person-info"><strong>${i===0?esc(state.displayName)+' (you)':esc(person.name)}</strong><small>${editing?'Draft allocation':i===0?(state.approved[c.id]?'Accepted':'Ready to review'):state.proposals[c.id]?'Waiting to review':i<=(c.initialApprovals??1)?'Accepted':'Waiting to review'}</small></div>${editing&&p.method==='custom'?`<input class="custom-input" aria-label="${esc(person.name)} share in dollars" inputmode="decimal" type="number" min="0" step=".01" value="${esc(p.allocation[i])}" data-draft-field="allocation" data-person="${i}">`:`<span class="amount" data-draft-share="${i}">${result.error?'—':money(result.allocation[i])}</span>`}</div>`).join('')}</section>`;}
function receiptReview(c,p){if(!p.receipt)return `<section class="card-section receipt-empty">${icon('file-text')}<h2>No receipt attached</h2><p class="info-text">Add a receipt to review and split individual items.</p>${button(icon('plus')+' Add receipt','begin-edit',`data-id="${c.id}"`,'secondary full')}</section>`;return `<section class="card-section"><button class="receipt-title" data-action="receipt" data-id="${c.id}" aria-expanded="${!!state.receiptOpen[c.id]}"><span>${icon('file-text')} Receipt</span>${icon(state.receiptOpen[c.id]?'chevron-down':'chevron-right')}</button><p class="receipt-source">${p.receipt.kind==='image'?'Attached photo':p.receipt.kind==='sample'?'Sample receipt':'Manually entered receipt'}${p.receipt.itemSource==='sample'?' · Sample items':''}</p>${state.receiptOpen[c.id]?`${p.receipt.image?`<img class="receipt-photo" src="${esc(p.receipt.image)}" alt="Attached receipt">`:''}${p.items.map(item=>`<div class="receipt-item"><span>${esc(item.name)}<small>${item.assignees.map(id=>{const i=chargePeople(c).findIndex(m=>m.id===id);return i===0?'You':esc(chargePeople(c)[i]?.name||'Unassigned');}).join(', ')||'Unassigned'}</small>${state.approved[c.id]&&p.method==='item'&&item.assignees.includes(chargePeople(c)[0].id)?'<small class="accepted-item">Accepted by you</small>':''}</span><strong>${money(item.amount)}</strong></div>`).join('')}<div class="receipt-item"><span>Tax</span><strong>${money(p.tax)}</strong></div><div class="receipt-item"><span>Tip</span><strong>${money(p.tip)}</strong></div>`:''}</section>`;}
function split(id){const c=pending.find(c=>c.id===id),p=currentProposal(c),invalid=p.method==='item'?calculateProposal(c,p).error:null;return `${backbar(c.name)}${state.approved[id]?'<div class="split-state"><span class="pill success">Waiting for the group</span></div>':''}${splitSummary(c)}<div class="split-meta">${icon('users')} ${currentApprovalCount(c)} of ${chargePeople(c).length} approved</div>${invalid?`<div class="callout neutral">${icon('file-text')}<span>${esc(invalid)}</span></div>`:''}${memberAllocations(c,p)}${receiptReview(c,p)}${state.approved[id]?'<div class="status-banner">'+icon('check-circle')+'<span>You accepted your '+(p.method==='item'?'items':'share')+'. Other members still review for themselves. This purchase remains pending.</span></div>':''}`;}
function itemEditor(c,d){const members=chargePeople(c);return `<section class="card-section item-editor"><div class="row"><h2>Receipt & items</h2>${d.receipt?'<span class="pill">Attached</span>':''}</div>${d.receipt?.image?`<img class="receipt-photo" src="${esc(d.receipt.image)}" alt="Draft receipt attachment">`:''}<label class="receipt-upload">${icon('plus')} ${d.receipt?.image?'Replace receipt photo':'Attach receipt photo'}<input id="receipt-upload" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><small>Local image only. Enter items below; no text is extracted.</small></label><div class="receipt-entry-actions">${button('Use sample items','sample-items',`data-id="${c.id}"`,'secondary')}${button('Enter an item','add-item',`data-id="${c.id}"`,'secondary')}</div>${d.receipt?.itemSource==='sample'?'<p class="receipt-source">Sample items for this preview · not extracted from your image</p>':''}${d.items.map((item,index)=>`<article class="item-draft"><div class="item-draft-fields"><label><span>Item ${index+1}</span><input aria-label="Item ${index+1} name" value="${esc(item.name)}" maxlength="60" data-draft-field="item-name" data-item="${item.id}"></label><label><span>Amount ($)</span><input type="number" min="0.01" step=".01" inputmode="decimal" aria-label="Item ${index+1} amount" value="${esc(item.amount)}" data-draft-field="item-amount" data-item="${item.id}"></label><button class="icon-btn" data-action="remove-item" data-id="${c.id}" data-item="${item.id}" aria-label="Remove item ${index+1}">${icon('x')}</button></div><div class="assignee-label">Who shared this?</div><div class="assignee-chips">${members.map((m,i)=>`<button data-action="assign-item" data-id="${c.id}" data-item="${item.id}" data-person="${m.id}" aria-pressed="${item.assignees.includes(m.id)}">${i===0?'You':esc(m.name)}</button>`).join('')}</div></article>`).join('')}${d.items.length?`<div class="receipt-adjustments"><label class="field"><span>Tax ($)</span><input type="number" min="0" step=".01" value="${esc(d.tax)}" data-draft-field="tax"></label><label class="field"><span>Tip ($)</span><input type="number" min="0" step=".01" value="${esc(d.tip)}" data-draft-field="tip"></label></div><p class="form-footnote">Tax and tip follow item amounts. Shared items divide equally among assigned members.</p>`:''}<p class="draft-validation" id="draft-total" role="status">${esc(calculateProposal(c,d).error||'Items and shares are ready to review.')}</p></section>`;}
function splitEdit(id){const c=pending.find(c=>c.id===id),d=state.splitDrafts[id];return `${backbar('Edit split')}${splitSummary(c,d)}<div class="segmented" role="group" aria-label="Draft split method">${[['item','By item'],['equal','Equally'],['custom','Custom']].map(([method,label])=>`<button class="${d.method===method?'active':''}" data-action="draft-method" data-id="${id}" data-method="${method}" aria-pressed="${d.method===method}">${label}</button>`).join('')}</div>${memberAllocations(c,d,true)}${itemEditor(c,d)}`;}
function splitFooter(id,editing=false){const c=pending.find(c=>c.id===id),p=currentProposal(c),invalid=p.method==='item'&&calculateProposal(c,p).error;return `<div class="footer-action"><div class="split-footer-buttons">${editing?button('Cancel','cancel-edit',`data-id="${id}"`,'secondary')+button('Submit proposal','submit-proposal',`data-id="${id}"`):button('Begin edit','begin-edit',`data-id="${id}"`,'secondary')+button(state.approved[id]?icon('check')+' Accepted':p.method==='item'?'Accept my items':'Accept my share','accept-split',`data-id="${id}" ${state.approved[id]||invalid?'disabled':''}`)}</div><p>${editing?'Nothing changes for the group until you submit.':'Only your own '+(p.method==='item'?'items are':'share is')+' accepted. Spending updates after settlement.'}</p></div>`;}
function invitations(){return `${backbar('Invitations')}<h1 class="page-title">You’re invited.</h1><p class="page-sub">A new shared plan starts here.</p>${invites.map(i=>state.invites[i.id]?`<section class="invitation"><div class="row">${stamp(i)}<span class="pill ${state.invites[i.id]==='accepted'?'success':'muted'}">${state.invites[i.id]==='accepted'?'Accepted':'Declined'}</span></div><h2>${i.name}</h2><p class="info-text">${state.invites[i.id]==='accepted'?'Waiting for all invitations to be resolved before the group activates. Your approved contribution cap is '+money(i.share)+'.':'You declined this invitation. No contribution will be collected.'}</p></section>`:`<section class="invitation"><div class="row">${stamp(i)}<span class="pill">Invitation</span></div><h2>${i.name}</h2><p class="info-text">${i.from} invited you · ${i.members} people</p><div class="subtle-divider"></div><div class="detail-row row"><span class="row-label">Group budget</span><span class="row-value">${money(i.budget)}</span></div><div class="detail-row row"><span class="row-label">Your contribution cap</span><span class="row-value">${money(i.share)}</span></div><p class="form-footnote">By accepting, you authorize up to ${money(i.share)} to be collected automatically when all invitations are accepted or declined and at least two members have joined. Review the final amount before authorizing any increase.</p><div class="actions-pair">${button('Decline','invite',`data-id="${i.id}" data-response="declined"`,'secondary')}${button('Accept · '+money(i.share)+' cap','invite',`data-id="${i.id}" data-response="accepted"`)}</div></section>`).join('')}<p class="form-footnote">Preview only. No contribution or transfer occurs.</p>`;}
function notifications(){return `${backbar('Notifications')}<h1 class="page-title">You’re in the loop.</h1><p class="page-sub">A few things from your people.</p><div class="list-menu">${pending.map(c=>`<button class="menu-row" data-action="split" data-id="${c.id}">${stamp(gById(c.group))}<span class="menu-copy">${esc(c.name)}<small>${state.approved[c.id]?'Your share is approved. Waiting for the group.':'Your '+money(currentPersonalAllocation(c))+' share is ready to review.'}</small></span>${icon('chevron-right')}</button>`).join('')}<button class="menu-row" data-action="invitations">${icon('mail')}<span class="menu-copy">New group invitations<small>${invites.filter(i=>!state.invites[i.id]).length} invitations to review</small></span>${icon('chevron-right')}</button></div>`;}
function profile(){return `${backbar('Your profile')}<div class="profile-identity">${avatar(people[0],true)}<h1>${esc(state.displayName)} Zacharias</h1><small>@connorz · Sample profile</small></div><div class="list-menu">${[['edit-profile','users','Personal details','Name and profile'],['notifications-settings','bell','Notifications','Keep up with your groups'],['privacy','shield','Privacy','Your information stays with your group'],['about','help-circle','About this preview','How this prototype works']].map(([a,i,t,s])=>`<button class="menu-row" data-action="${a}">${icon(i)}<span class="menu-copy">${t}<small>${s}</small></span>${icon('chevron-right')}</button>`).join('')}</div>`;}
function groupMenu(type,id){const g=gById(id);const memberCount=g.members;const title={funds:'Funds',card:'Your card',members:'Members',budget:'Budget',settings:'Group settings'}[type];let body='';if(type==='funds')body=`<section class="card-section"><div class="eyebrow">Your balance in ${esc(g.name)}</div><div class="spending-total">${money(g.balance)}</div><p class="spending-caption">${money(g.available)} available in the group</p><div class="actions-pair">${button(icon('plus')+' Add funds','fund-form',`data-id="${id}" data-kind="add"`)}${button(icon('arrow-up-right')+' Withdraw','fund-form',`data-id="${id}" data-kind="withdraw"`,'secondary')}</div></section><div class="callout neutral">${icon('info')}<span>${pending.some(c=>c.group===id)?'Withdrawals are unavailable while this group has an unsettled split.':'Only your own available balance can be withdrawn.'} Funding reviews in this preview never move money.</span></div><section class="card-section"><div class="row"><div><strong style="font-size:12px">Auto-refill</strong><p class="info-text">Top up to your share each period.</p></div><button class="toggle ${state.autofill[id]!==false?'on':''}" role="switch" aria-checked="${state.autofill[id]!==false}" aria-label="Auto-refill" data-action="toggle" data-id="${id}" data-key="autofill"></button></div></section>`;if(type==='card')body=`<button class="card-launch" data-action="wallet" data-id="${id}" aria-label="Open mock Apple Pay">${cardVisual(g)}</button><p class="card-caption">Sample virtual card · No wallet or payment integration</p><section class="card-section" style="margin-top:24px"><div class="row"><div><strong style="font-size:12px">Freeze card</strong><p class="info-text">Temporarily pause this card.</p></div><button class="toggle ${state.frozen[id]?'on':''}" role="switch" aria-checked="${!!state.frozen[id]}" aria-label="Freeze card" data-action="toggle" data-id="${id}" data-key="frozen"></button></div></section><div class="list-menu"><button class="menu-row" data-action="card-details" data-id="${id}">${icon('credit-card')}<span>Card details</span>${icon('chevron-right')}</button></div>`;if(type==='members')body=`<h1 class="page-title">Your people.</h1><p class="page-sub">${memberCount} members · ${esc(g.name)}</p><section class="card-section">${(g.people||people.slice(0,memberCount)).map((p,i)=>`<div class="person-row">${avatar(p)}<div class="person-info"><strong>${i===0?esc(state.displayName)+' (you)':esc(p.name)}</strong><small>${i===0?'Group creator':'Member'}</small></div><span class="pill success">${g.forming?'Invited':'Up to date'}</span></div>`).join('')}</section>`;if(type==='budget')body=`<section class="card-section"><div class="eyebrow">Current group budget</div><div class="spending-total">${money(g.budget)}</div><p class="spending-caption">${g.period} · ${money(g.budget/memberCount)} per person</p></section><form data-form="budget" data-id="${id}"><label class="field"><span>Propose a new budget</span><input name="budget" type="number" min="1" max="100000" step=".01" required value="${g.budget}"><small>Everyone must agree. Increases and decreases take effect next period.</small></label><p class="form-error" role="alert"></p><button class="button full" type="submit">Review proposal ${icon('arrow-right')}</button></form>${g.proposedBudget?'<div class="callout">'+icon('info')+'<span>Your '+money(g.proposedBudget)+' budget proposal is waiting for the other members. The current budget is unchanged.</span></div>':''}`;if(type==='settings')body=`<div class="settings-group">${stamp(g)}<div><strong>${esc(g.name)}</strong><small>${g.members} members</small></div></div><div class="list-menu settings-menu">${[['group-edit','settings','Group name & photo','Make it yours'],['members','users','Members',g.members+' people'],['budget','calendar','Budget',money(g.budget)+' · '+g.period.toLowerCase()]].map(([route,i,label,detail])=>`<button class="menu-row" data-action="group-menu" data-id="${id}" data-menu="${route}">${icon(i)}<span class="menu-copy">${label}<small>${detail}</small></span>${icon('chevron-right')}</button>`).join('')}</div><section class="card-section"><label class="field" style="margin:0"><span>Default split</span><select id="default-split" data-id="${id}"><option ${g.defaultSplit!=='item'?'selected':''} value="equal">Equally</option><option ${g.defaultSplit==='item'?'selected':''} value="item">By item</option></select><small>Used for new purchases. Without a receipt, current shares start equal. Existing splits stay unchanged.</small></label></section>`;return backbar(title)+body;}
function createGroup(){return `${backbar('New group')}<h1 class="page-title">Make room for together.</h1><p class="page-sub">Start with your people and a shared budget.</p><form data-form="create"><label class="field"><span>Group name</span><input name="name" placeholder="e.g. The apartment" maxlength="32" required></label><div class="fields-row"><label class="field"><span>Group budget ($)</span><input name="budget" type="number" min="1" max="100000" step=".01" placeholder="300" required></label><label class="field"><span>Period</span><select name="period"><option>Every month</option><option>Every 2 weeks</option><option>Every week</option></select></label></div><label class="field"><span>Invite your people</span><input name="members" placeholder="maya, jordan" required><small>Enter 1–7 names separated by commas.</small></label><div class="callout">${icon('info')}<span>Everyone reviews their contribution cap first. Contributions collect automatically only after all invitations are resolved and at least two people join. Any increase above an approved cap needs fresh approval.</span></div><p class="form-error" role="alert"></p><button class="button full" type="submit">Review group ${icon('arrow-right')}</button><p class="form-footnote">This preview creates a local sample group. It sends no messages and collects no money.</p></form>`;}
function render(enter=false){const r=current();let html='',footer='';switch(r.type){case'home':html=home();break;case'all-pending':html=allPending();break;case'groups':html=groupsPage();break;case'spending':html=spending();break;case'group':html=groupDetail(r.id);break;case'wallet':html=wallet(r.id);break;case'group-edit':html=groupEdit(r.id);break;case'split':html=split(r.id);footer=splitFooter(r.id);break;case'split-edit':html=splitEdit(r.id);footer=splitFooter(r.id,true);break;case'history':html=chargeHistory(r.id);break;case'invitations':html=invitations();break;case'notifications':html=notifications();break;case'profile':html=profile();break;case'create':html=createGroup();break;case'statistics':html=spending(r.id);break;default:html=groupMenu(r.type,r.id);}$('#app').innerHTML=`<section class="screen ${enter?'enter':''} ${r.type==='split'||r.type==='split-edit'?'split-screen':''} ${r.type==='wallet'?'wallet-screen':''}" tabindex="-1">${html}</section>${footer}${!state.stack.length?navBar():''}`;$('.screen').scrollTop=state.scroll[routeKey()]||0;bindSplitPin();if(enter){const h=$('h1')||$('.backbar strong');if(h){h.tabIndex=-1;h.classList.add('focus-heading');h.focus({preventScroll:true});}}}
let lastFocus;
function modal(title,body){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${body}</section></div>`;$('#app').inert=true;requestAnimationFrame(()=>$('.modal input, .modal button, .modal select')?.focus());}
function closeModal(){ $('#modal-root').innerHTML='';$('#app').inert=false;state.modal=null;if(lastFocus?.isConnected)lastFocus.focus(); }
function simpleModal(title,body){modal(title,`<p class="info-text">${body}</p>${button('Got it','close-modal','','full')}`);}
function showFundForm(id,kind){const g=gById(id);if(kind==='withdraw'&&pending.some(c=>c.group===id)){simpleModal('A split is still pending','You can withdraw after every open split in '+esc(g.name)+' has settled. Approving your own share alone does not settle a split.');return;}modal(kind==='add'?'Add funds':'Withdraw funds',`<form data-form="funds" data-id="${id}" data-kind="${kind}"><label class="field"><span>Amount ($)</span><input name="amount" type="number" min="0.01" step=".01" ${kind==='withdraw'?`max="${g.balance}"`:''} placeholder="0.00" required><small>${kind==='withdraw'?'Your available balance: '+money(g.balance):'Add to your balance in '+esc(g.name)}</small></label><p class="form-error" role="alert"></p><button class="button full" type="submit">Review ${kind==='add'?'contribution':'withdrawal'}</button><p class="form-footnote">Preview only. No payment method is connected.</p></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(Date.now()<suppressCardClickUntil&&b.closest('[data-carousel]')){e.preventDefault();return;}const {action,id,menu,tab,dir,method,response,key,kind}=b.dataset;switch(action){case'carousel':setCarousel(id,Number(b.dataset.panel));break;case'wallet':if(Date.now()<suppressCardClickUntil)break;state.paymentResult=null;push('wallet',id);break;case'wallet-review':push('split',state.paymentResult);break;case'wallet-done':back();break;case'tab':nav(tab);break;case'back':back();break;case'profile':push('profile');break;case'notifications':state.notice=false;push('notifications');break;case'invitations':push('invitations');break;case'all-pending':push('all-pending');break;case'create':push('create');break;case'group':push('group',id);break;case'group-menu':if(menu==='group-edit'){photoReadVersion++;state.photoDraft={id,photo:groupPhoto(gById(id))};}push(menu,id);break;case'split':push('split',id);break;case'close-modal':closeModal();break;case'month':saveScroll();state.month=Math.max(0,Math.min(11,state.month+Number(dir)));render();break;case'legend':saveScroll();if(current().type!=='statistics')state.filter=state.filter===id?'all':id;render();break;case'receipt':saveScroll();state.receiptOpen[id]=!state.receiptOpen[id];render();break;case'begin-edit':beginSplitEdit(id);break;case'cancel-edit':back();break;case'draft-method':{const d=state.splitDrafts[id];if(!d)break;d.method=method;if(method==='custom')d.allocation=[...currentAllocation(pending.find(c=>c.id===id))];saveScroll();render();break;}case'assign-item':{const d=state.splitDrafts[id],item=d?.items.find(item=>item.id===b.dataset.item);if(!item)break;const person=b.dataset.person;item.assignees=item.assignees.includes(person)?item.assignees.filter(p=>p!==person):[...item.assignees,person];saveScroll();render();break;}case'remove-item':{const d=state.splitDrafts[id];if(!d)break;d.items=d.items.filter(item=>item.id!==b.dataset.item);saveScroll();render();break;}case'add-item':{const d=state.splitDrafts[id];if(!d)break;d.receipt ||= {kind:'manual',name:'Manually entered receipt',itemSource:'manual'};d.items.push({id:'item-'+(++state.draftSequence),name:'',amount:'',assignees:[]});saveScroll();render();break;}case'sample-items':loadSampleItems(id);saveScroll();render();break;case'submit-proposal':{const result=submitSplitProposal(id);if(result.error){toast(result.error);break;}back();toast(result.changed?'Proposal submitted. Everyone reviews this version again.':'No changes to submit. Existing approvals were preserved.');break;}case'accept-split':{const result=acceptSplit(id);if(result.error){toast(result.error);break;}saveScroll();render();toast('You accepted your share. Waiting for the other members.');break;}case'invite':state.invites[id]=response;if(response==='accepted'&&!groups.some(g=>g.id===id)){const invite=invites.find(i=>i.id===id);groups.push({...invite,members:invite.members,balance:0,power:0,available:0,total:0,forming:true,contributionCap:invite.share});}saveScroll();render();toast(response==='accepted'?'Invitation accepted in this preview. No contribution collected.':'Invitation declined. No contribution collected.');break;case'toggle':state[key][id]=!(state[key][id]??(key!=='frozen'));saveScroll();render();toast(key==='frozen'?(state.frozen[id]?'Card frozen in this preview.':'Card unfrozen in this preview.'):'Preference updated for this preview.');break;case'fund-form':showFundForm(id,kind);break;case'confirm-funds':closeModal();toast('Review complete. This preview did not transfer any money.');break;case'confirm-create':{const d=state.groupDraft;groups.push({id:'new-'+Date.now(),name:d.name,icon:'users',tone:'green',members:d.count,balance:0,power:0,available:0,total:0,budget:d.budget,period:d.period,forming:true,people:[people[0],...d.invitees.map((name,index)=>({name,initials:name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase(),tone:['maya','jordan','sam'][index%3]}))]});closeModal();state.stack=[];state.tab='groups';render();toast('Sample group created. Invitations and contributions are simulated.');break;}case'confirm-budget':gById(id).proposedBudget=state.budgetDraft;closeModal();render();toast('Proposal saved locally. Your current budget is unchanged.');break;case'edit-profile':modal('Personal details',`<form data-form="profile"><label class="field"><span>First name</span><input name="name" maxlength="24" required value="${esc(state.displayName)}"></label><button class="button full" type="submit">Save changes</button><p class="form-footnote">Only the name shown in this preview will change.</p></form>`);break;case'notifications-settings':modal('Notifications',`<p class="info-text">Choose what you would like to hear about.</p><div class="detail-row row"><span class="row-label">Split updates</span><button class="toggle ${state.notifySplits!==false?'on':''}" role="switch" aria-checked="${state.notifySplits!==false}" aria-label="Split updates" data-action="local-notify" data-key="notifySplits"></button></div><div class="detail-row row"><span class="row-label">Group invitations</span><button class="toggle ${state.notifyInvites!==false?'on':''}" role="switch" aria-checked="${state.notifyInvites!==false}" aria-label="Group invitations" data-action="local-notify" data-key="notifyInvites"></button></div><p class="form-footnote">No push notifications are sent from this preview.</p>${button('Done','close-modal','','full')}`);break;case'local-notify':state[key]=!(state[key]??true);b.classList.toggle('on',state[key]);b.setAttribute('aria-checked',String(state[key]));break;case'privacy':simpleModal('Private by design','In the product, your groups are visible only to their members. This standalone preview uses sample data, makes no account requests, and stores no personal details.');break;case'about':simpleModal('A space to explore','This is an interactive design prototype for chipin. All people, balances, cards, and purchases are sample data. Changes stay in this browser page and reset on reload. No real money moves.');break;case'card-details':simpleModal('Your sample card','Card ending 4826 · Connor Zacharias · '+esc(gById(id).name)+'. This visual card has no real card number, security code, wallet connection, or payment capability.');break;case'charge':{const c=charges.find(x=>x.id===id);modal(c.name,`<div class="row"><span class="row-label">${gById(c.group).name} · ${c.date}</span><span class="pill success">Settled</span></div><div class="spending-total" style="margin:22px 0">${money(c.amount)}</div><div class="detail-row row"><span class="row-label">Your share</span><span class="row-value">${money(c.amount)}</span></div><div class="detail-row row"><span class="row-label">Split method</span><span class="row-value">Equally</span></div><p class="form-footnote">All members approved. Sample transaction for this design preview.</p>${button('Done','close-modal','','full')}`);break;}}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);const err=$('.form-error',form);const fail=t=>{if(err)err.textContent=t;};switch(form.dataset.form){case'payment':{const result=simulatePayment(form.dataset.id,'Blue Bottle',Number(f.get('amount')));if(result.error)return fail(result.error);saveScroll();state.scroll[routeKey()]=0;render(true);break;}case'group-edit':{const name=String(f.get('name')).trim();if(!name)return fail('Enter a group name.');const g=gById(form.dataset.id);g.name=name.slice(0,32);if(state.photoDraft?.id===g.id&&state.photoDraft.photo)g.photo=state.photoDraft.photo;state.photoDraft=null;back();toast('Group details updated in this preview.');break;}case'create':{const name=String(f.get('name')).trim(),budget=Number(f.get('budget')),members=String(f.get('members')).split(',').map(s=>s.trim()).filter(Boolean);if(!name||!members.length)return fail('Add a group name and at least one person.');if(members.length>7)return fail('This preview supports up to seven invitees.');if(!Number.isFinite(budget)||budget<=0)return fail('Enter a positive group budget.');state.groupDraft={name,budget,count:members.length+1,invitees:members,period:String(f.get('period'))};modal('Review your group',`<div class="detail-row row"><span class="row-label">Group</span><span class="row-value">${esc(name)}</span></div><div class="detail-row row"><span class="row-label">Budget</span><span class="row-value">${money(budget)}</span></div><div class="detail-row row"><span class="row-label">Your contribution cap</span><span class="row-value">${money(Math.ceil(budget*100/(members.length+1))/100)}</span></div><p class="form-footnote">${members.length+1} people · ${esc(f.get('period'))}. By continuing, you authorize this cap at activation, after all invitations are resolved with at least two members. No real contribution or invitation occurs in this preview.</p>${button('Create sample group','confirm-create','','full')}${button('Keep editing','close-modal','','secondary full')}`);break;}case'funds':{const amount=Number(f.get('amount'));const g=gById(form.dataset.id);if(!Number.isFinite(amount)||amount<=0||Math.abs(amount*100-Math.round(amount*100))>.00001)return fail('Enter a positive amount with at most two decimal places.');if(form.dataset.kind==='withdraw'&&amount>g.balance)return fail('The amount exceeds your available balance.');modal('Review '+(form.dataset.kind==='add'?'contribution':'withdrawal'),`<div class="eyebrow">${esc(g.name)}</div><div class="spending-total" style="margin:12px 0 20px">${money(amount)}</div><p class="info-text">This is a form preview. Confirming completes the review step without charging a card, transferring funds, or changing your balance.</p>${button('Finish review','confirm-funds','','full')}${button('Cancel','close-modal','','secondary full')}`);break;}case'budget':{const budget=Number(f.get('budget'));if(!Number.isFinite(budget)||budget<=0)return fail('Enter a positive budget.');if(budget===gById(form.dataset.id).budget)return fail('Enter a different budget to propose a change.');state.budgetDraft=budget;modal('Review budget proposal',`<div class="spending-total">${money(budget)}</div><p class="info-text" style="margin-top:15px">${money(budget/gById(form.dataset.id).members)} per member. Everyone must approve this proposal. It takes effect next period; current balances and this period’s budget stay unchanged.</p><p class="form-footnote">This saves a proposal only in the preview.</p>${button('Propose to group','confirm-budget',`data-id="${form.dataset.id}"`,'full')}${button('Keep editing','close-modal','','secondary full')}`);break;}case'profile':state.displayName=String(f.get('name')).trim()||'Connor';closeModal();render();toast('Your preview profile has been updated.');break;}});
document.addEventListener('change',e=>{if(e.target.id==='charge-filter'){saveScroll();state.filter=e.target.value;render();}if(e.target.matches('[name="group-photo"]')){photoReadVersion++;state.photoDraft={id:current().id,photo:groupPhotos[e.target.value]};const preview=$('#group-photo-preview');if(preview)preview.src=state.photoDraft.photo;}if(e.target.id==='photo-upload'){readGroupPhoto(e.target);}if(e.target.id==='receipt-upload'){readReceipt(e.target);}if(e.target.id==='default-split'){gById(e.target.dataset.id).defaultSplit=e.target.value;toast('Default split updated for future sample purchases.');}});
document.addEventListener('input',e=>{const field=e.target.dataset.draftField;if(!field||current().type!=='split-edit')return;const c=pending.find(c=>c.id===current().id),d=state.splitDrafts[c.id];if(field==='allocation')d.allocation[Number(e.target.dataset.person)]=e.target.value;else if(field==='tax'||field==='tip')d[field]=e.target.value;else{const item=d.items.find(item=>item.id===e.target.dataset.item);if(item)item[field==='item-name'?'name':'amount']=e.target.value;}refreshDraftSummary(c,d);});
document.addEventListener('keydown',e=>{const m=$('.modal');if(!m)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const f=[...m.querySelectorAll('button:not(:disabled),input,select,a[href]')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();if(e.target.closest('.brand')){e.preventDefault();nav('home');}});
window.addEventListener('hashchange',()=>{if(location.hash==='#home')nav('home');});

function groupEdit(id){const g=gById(id),photo=state.photoDraft?.id===id?state.photoDraft.photo:groupPhoto(g);return `${backbar('Group name & photo')}<h1 class="page-title">Make it yours.</h1><p class="page-sub">A familiar face for your shared plans.</p><form data-form="group-edit" data-id="${id}"><div class="photo-edit-preview"><img id="group-photo-preview" src="${esc(photo||groupPhotos.apartment)}" alt="Selected group photo"></div><label class="field"><span>Group name</span><input name="name" value="${esc(g.name)}" maxlength="32" required></label><fieldset class="photo-options"><legend>Group photo</legend>${Object.entries(groupPhotos).map(([key,src])=>`<label><input type="radio" name="group-photo" value="${key}" ${photo===src?'checked':''}><img src="${src}" alt="${key==='weekend'?'Dinner table':key==='roadtrip'?'Forest':'Apartment'}"></label>`).join('')}</fieldset><label class="upload-photo">${icon('plus')} Choose your own photo<input type="file" id="photo-upload" accept="image/jpeg,image/png,image/webp,image/gif"><small>JPG, PNG, WebP or GIF · up to 5 MB · stays on this page</small></label><p class="form-error" role="alert"></p><button class="button full" type="submit">Save changes</button></form>`;}
function readGroupPhoto(input){const file=input.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>5*1024*1024){$('.form-error').textContent='Choose a JPG, PNG, WebP or GIF up to 5 MB.';input.value='';return;}const id=current().id,version=++photoReadVersion,reader=new FileReader();reader.onload=()=>{if(version!==photoReadVersion||current().type!=='group-edit'||current().id!==id)return;state.photoDraft={id,photo:String(reader.result)};$('#group-photo-preview').src=state.photoDraft.photo;document.querySelectorAll('[name="group-photo"]').forEach(r=>r.checked=false);$('.form-error').textContent='';};reader.onerror=()=>{$('.form-error').textContent='This photo could not be read. Try another image.';};reader.readAsDataURL(file);}
function contactless(){return `<svg class="contactless" viewBox="0 0 72 72" fill="none" aria-hidden="true"><circle cx="36" cy="36" r="32" stroke="#1683ff" stroke-width="4"/><path d="M20 63V28a6 6 0 0 1 6-6h20a6 6 0 0 1 6 6v35" stroke="#1683ff" stroke-width="2.5"/><path d="M33 27h6" stroke="#1683ff" stroke-width="2.5" stroke-linecap="round"/></svg>`;}
function wallet(id){const g=gById(id),c=pending.find(c=>c.id===state.paymentResult);if(c)return `${backbar('')}<div class="payment-success native-success"><div class="success-circle">${icon('check')}</div><h1>Payment confirmed</h1><div class="payment-amount">${money(c.total)}</div><p>Blue Bottle</p><div class="wallet-card-arrival">${cardVisual(g)}</div><p class="info-text">Your ${money(currentPersonalAllocation(c))} share is ready to review.</p>${button('Review split','wallet-review','','full')}${button('Back to group','wallet-done','','secondary full')}</div>`;return `${backbar('')}<div class="native-wallet-card wallet-card-arrival">${cardVisual(g)}</div><div class="reader-prompt">${contactless()}<h1>Hold Near Reader</h1></div><form class="wallet-bottom" data-form="payment" data-id="${id}"><label class="wallet-amount-widget"><span>Amount<small>Blue Bottle</small></span><span class="wallet-amount-input"><span>$</span><input name="amount" aria-label="Purchase amount in dollars" type="number" min="0.01" step=".01" value="24.00" required></span></label><p class="form-error" role="alert"></p><button class="button full payment-button" type="submit" ${state.frozen[id]||g.forming?'disabled':''}>Simulate payment</button>${state.frozen[id]||g.forming?`<p class="form-footnote">${state.frozen[id]?'Unfreeze this card to continue.':'This group must activate before purchases.'}</p>`:''}</form>`;}
function simulatePayment(id,merchant,amount){const g=gById(id);if(state.paymentResult)return {error:'This payment was already simulated.'};if(g.forming||state.frozen[id])return {error:'This group card is not available for purchases.'};if(!merchant.trim())return {error:'Enter a merchant name.'};if(!Number.isFinite(amount)||amount<=0||Math.abs(amount*100-Math.round(amount*100))>.00001)return {error:'Enter a positive amount with at most two decimal places.'};if(Math.round(amount*100)>Math.round(g.available*100))return {error:'This amount exceeds the group’s available funds.'};const members=(g.people||people.slice(0,g.members)).map(p=>({...p}));const c={id:'simulated-'+(++state.paymentSequence),name:merchant.trim().slice(0,48),merchant:merchant.trim().slice(0,48),group:id,total:Math.round(amount*100)/100,members:members.length,people:members,allocation:equalAllocation(amount,members.length),initialMethod:g.defaultSplit||'equal',initialApprovals:0,month:9,date:'Oct 17 · Just now',icon:'shopping-bag',simulated:true};pending.unshift(c);g.available=(Math.round(g.power*100)-pending.filter(p=>p.group===id).reduce((sum,p)=>sum+Math.round(p.total*100),0))/100;state.paymentResult=c.id;state.notice=true;return c;}
function loadSampleItems(id){const c=pending.find(c=>c.id===id),d=state.splitDrafts[id];if(!d)return;const members=chargePeople(c);d.receipt={...(d.receipt||{kind:'sample',name:'Sample receipt'}),itemSource:'sample'};if(c.id==='juniper'){d.items=initialItems(c);d.tax=10.2;d.tip=24;}else{const parts=equalAllocation(c.total,2);d.items=parts.filter(n=>n>0).map((amount,i)=>({id:'sample-'+i,name:i===0?'Sample purchase':'Sample extras',amount,assignees:members.map(m=>m.id)}));d.tax=0;d.tip=0;}}
function refreshDraftSummary(c,d){const result=calculateProposal(c,d);const summary=$('#sticky-draft-amount');if(summary)summary.textContent=(result.error?'Draft incomplete':'Draft '+money(result.allocation[0]))+' · not sent';const validation=$('#draft-total');if(validation)validation.textContent=result.error||'Items and shares are ready to review.';document.querySelectorAll('[data-draft-share]').forEach(el=>el.textContent=result.error?'—':money(result.allocation[Number(el.dataset.draftShare)]));}
function readReceipt(input){const file=input.files?.[0],route=current(),draft=state.splitDrafts[route.id];if(!file||route.type!=='split-edit'||!draft)return;if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>5*1024*1024){toast('Choose a JPG, PNG, WebP or GIF up to 5 MB.');input.value='';return;}const generation=draft.generation,id=route.id,version=(draft.uploadVersion||0)+1;draft.uploadVersion=version;const reader=new FileReader();reader.onload=()=>{const active=state.splitDrafts[id];if(current().type!=='split-edit'||current().id!==id||!active||active.generation!==generation||active.uploadVersion!==version)return;active.receipt={kind:'image',name:file.name,image:String(reader.result),itemSource:active.receipt?.itemSource||'manual'};saveScroll();render();toast('Receipt attached locally. Enter the items to continue.');};reader.onerror=()=>toast('The receipt image could not be read. Try another image.');reader.readAsDataURL(file);}
function bindSplitPin(){if(!['split','split-edit'].includes(current().type))return;const screen=$('.screen'),summary=$('.split-summary');if(!summary)return;const update=()=>summary.style.setProperty('--compact',String(Math.max(0,Math.min(1,(screen.scrollTop-24)/72))));screen.addEventListener('scroll',update,{passive:true});update();}
let swipeStart=null,suppressCardClickUntil=0,photoReadVersion=0;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-carousel]');if(el)swipeStart={id:el.dataset.carousel,x:e.clientX,y:e.clientY};});
document.addEventListener('pointerup',e=>{if(!swipeStart)return;const start=swipeStart;swipeStart=null;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.3){suppressCardClickUntil=Date.now()+500;e.preventDefault();setCarousel(start.id,(state.carousel[start.id]||0)===0?1:0);}});
document.addEventListener('pointercancel',()=>{swipeStart=null;});
document.addEventListener('keydown',e=>{const carousel=e.target.closest('[data-carousel]');if(carousel&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();setCarousel(carousel.dataset.carousel,(state.carousel[carousel.dataset.carousel]||0)===0?1:0);}});
render();
